#include "PluginProcessor.h"
#include "SoundEditor.h"
#include "InstrumentSettingsPicker.h"
#include <iostream>
#include <stdexcept>
namespace {
void check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
juce::Component* find(juce::Component& root,const juce::String& id){if(root.getComponentID()==id)return &root;for(auto* child:root.getChildren())if(auto* found=find(*child,id))return found;return nullptr;}
template<class T>T& control(juce::Component& root,const char* id){auto* c=dynamic_cast<T*>(find(root,id));check(c!=nullptr,"Envelope audit control missing");return *c;}
void click(juce::Component& root,const char* id){control<juce::TextButton>(root,id).onClick();}
void sameAudio(const juce::AudioBuffer<float>& a,const juce::AudioBuffer<float>& b,const char* message){check(a.getNumChannels()==b.getNumChannels() && a.getNumSamples()==b.getNumSamples(),"Envelope audit buffer mismatch");for(int ch=0;ch<a.getNumChannels();++ch)for(int n=0;n<a.getNumSamples();++n)check(std::abs(a.getSample(ch,n)-b.getSample(ch,n))<2e-6f,message);}
struct Rig {
    DrumAudioProcessor p{true};juce::String kit,id;double rate;int block;
    Rig(const juce::File& file,double hz,int frames):rate(hz),block(frames){p.newKit();auto s=p.getLibrary().snapshot();kit=s.activeKit;id=p.getLibrary().addInstrument(kit,s.kits[0].groups[0].id).id;auto layout=p.getBusesLayout();layout.outputBuses.set(1,juce::AudioChannelSet::stereo());layout.outputBuses.set(2,juce::AudioChannelSet::stereo());check(p.setBusesLayout(layout),"Envelope audit bus layout");p.prepareToPlay(rate,block);p.getSampleEngine().requestLoad(kit,id,file);settle();for(int n=0;n<2;++n){drum::MixerControls mix;mix.output=n+1;check(p.getLibrary().setReturnMixer(kit,n,mix).ok,"Envelope audit return routing");}}
    void settle(){p.getEffects().sync();check(p.getSampleEngine().waitForLoading(10000),"Envelope audit bank load");}
    drum::InstrumentControls current(){auto s=p.getLibrary().snapshot();return drum::findInstrument(*drum::activeKit(s),id)->controls;}
    void set(const drum::InstrumentControls& c){check(p.getLibrary().setControls(kit,id,c).ok,"Envelope audit controls");settle();}
    juce::AudioBuffer<float> hit(){settle();p.getSampleEngine().stop();juce::AudioBuffer<float> silence(6,block);juce::MidiBuffer midi;p.processBlock(silence,midi);const int count=(int)(rate*.5),release=(int)(rate*.17);juce::AudioBuffer<float> result(6,count);for(int at=0;at<count;){int frames=juce::jmin(block,count-at);juce::AudioBuffer<float> audio(6,frames);midi.clear();if(at==0)midi.addEvent(juce::MidiMessage::noteOn(1,21,(juce::uint8)100),0);if(release>=at && release<at+frames)midi.addEvent(juce::MidiMessage::noteOff(1,21),release-at);p.processBlock(audio,midi);for(int ch=0;ch<6;++ch)result.copyFrom(ch,at,audio,ch,0,frames);at+=frames;}return result;}
};
}
void runEnvelopeAuditTests(){
    auto file=juce::File::getCurrentWorkingDirectory().getChildFile("envelope-roundtrip.wav");file.deleteFile();
    {juce::WavAudioFormat format;std::unique_ptr<juce::AudioFormatWriter> writer(format.createWriterFor(file.createOutputStream().release(),48000,2,24,{},0));check(writer!=nullptr,"Envelope audit writer");juce::AudioBuffer<float> data(2,48000);for(int n=0;n<48000;++n){data.setSample(0,n,.1f+.3f*std::sin(n*juce::MathConstants<double>::twoPi*220/48000));data.setSample(1,n,-.05f+.2f*std::sin(n*juce::MathConstants<double>::twoPi*330/48000));}check(writer->writeFromAudioSampleBuffer(data,0,48000),"Envelope audit fixture");}
    {Rig defaults(file,48000,128);auto c=defaults.current();check(c==drum::newInstrumentControls(),"New instrument processing stages not off");check(!defaults.p.autoRemapLiveClips(),"New setup checkbox not off");auto labelled=c;labelled.tuning=13.12345;check(defaults.p.getSampleEngine().displayKey(defaults.id,labelled,{}).second==0,"Disabled pitch stage still transposed the key label");labelled.sound.bypassPitch=0;check(defaults.p.getSampleEngine().displayKey(defaults.id,labelled,{}).second==labelled.tuning,"Enabled pitch key fallback lost transposition");InstrumentSettingsPicker picker;check(!picker.selected().any(),"Preset picker not initially unticked");SoundEditor editor(defaults.p);editor.setSize(1200,850);auto s=defaults.p.getLibrary().snapshot();editor.select(defaults.kit,drum::findInstrument(*drum::activeKit(s),defaults.id));for(int page:{0,1,3,7,8}){click(editor,("edit-tab-"+juce::String(page)).toRawUTF8());check(!control<juce::ToggleButton>(editor,"editor-stage-enabled").getToggleState(),"New processing tick box checked by default");}click(editor,"edit-tab-1");auto& enabled=control<juce::ToggleButton>(editor,"editor-stage-enabled");enabled.setToggleState(true,juce::sendNotificationSync);check(defaults.current().sound.mode==2 && defaults.current().sound.bypassAmplitude==0,"Amplitude checkbox did not engage Envelope mode");}
    for(double rate:{44100.,48000.,96000.})for(int block:{64,512})for(int stage=0;stage<3;++stage)for(bool send:{false,true}){
        Rig r(file,rate,block);auto c=drum::InstrumentControls{};c.sound.mode=2;c.sound.sendA=c.sound.sendB=0;c.sound.envelopes[0]=drum::adsrShape(20,80,.3,160);c.sound.pitchAmount=7;c.sound.envelopes[1]=drum::adsrShape(15,60,.2,150);c.sound.filterOn=1;c.sound.cutoff=1700;c.sound.filterAmount=-2;c.sound.envelopes[2]=drum::adsrShape(10,90,.4,180);
        auto branch=std::make_shared<drum::SendProcessing>();branch->sound=c.sound;branch->sound.envelopes[0].points[1].bend=-.2;branch->sound.envelopes[1].points[1].bend=.1;branch->tuning=-3;c.sendProcessing[0]=branch;r.set(c);
        SoundEditor editor(r.p);editor.setSize(1200,850);auto s=r.p.getLibrary().snapshot();editor.select(r.kit,drum::findInstrument(*drum::activeKit(s),r.id));click(editor,"edit-tab-1");if(send)control<juce::ComboBox>(editor,"waveform-view").setSelectedId(3,juce::sendNotificationSync);click(editor,stage==0?"overlay-amplitude":stage==1?"overlay-pitch":"filter-envelope-tab");
        auto before=r.current();auto baseline=r.hit();auto& enabled=control<juce::ToggleButton>(editor,"editor-stage-enabled");check(enabled.getToggleState(),"Active audit stage displayed off");enabled.setToggleState(false,juce::sendNotificationSync);auto bypassed=r.hit();auto retained=r.current();const auto& a=send?before.sendProcessing[0]->sound:before.sound;const auto& b=send?retained.sendProcessing[0]->sound:retained.sound;check(a.envelopes==b.envelopes && a.pitchAmount==b.pitchAmount && a.filterAmount==b.filterAmount && a.cutoff==b.cutoff,"Disabling changed saved envelope settings");
        double difference=0;const int ch=send?2:0;for(int n=0;n<baseline.getNumSamples();++n)difference+=std::abs(baseline.getSample(ch,n)-bypassed.getSample(ch,n));if(difference<=.01)std::cerr<<"Audit no change: rate="<<rate<<" block="<<block<<" stage="<<stage<<" send="<<send<<" wetPeak="<<baseline.getMagnitude(ch,0,baseline.getNumSamples())<<" dryPeak="<<bypassed.getMagnitude(ch,0,bypassed.getNumSamples())<<" ampOff="<<b.bypassAmplitude<<" pitchOff="<<b.bypassPitch<<" filter="<<b.filterOn<<"\n";check(difference>.01,"Envelope switch did not change audible output");
        juce::MemoryBlock offState;r.p.getStateInformation(offState);Rig recalled(file,rate,block);recalled.p.setStateInformation(offState.getData(),(int)offState.getSize());recalled.p.prepareToPlay(rate,block);auto restored=recalled.p.getLibrary().snapshot();check(drum::findInstrument(*drum::activeKit(restored),r.id)->controls==retained,"Disabled envelope state changed on recall");sameAudio(bypassed,recalled.hit(),"Disabled envelope audio changed on recall");
        enabled.setToggleState(true,juce::sendNotificationSync);check(r.current()==before,"Re-enable did not restore exact saved controls");auto onAgain=r.hit();sameAudio(baseline,onAgain,"Re-enable did not restore the previous triggered sound");juce::MemoryBlock onState;r.p.getStateInformation(onState);recalled.p.setStateInformation(onState.getData(),(int)onState.getSize());recalled.p.prepareToPlay(rate,block);sameAudio(baseline,recalled.hit(),"Enabled envelope audio changed on recall");
        if(send){for(int other:{0,4})for(int n=0;n<baseline.getNumSamples();++n)for(int ch=other;ch<other+2;++ch)check(std::abs(baseline.getSample(ch,n)-bypassed.getSample(ch,n))<2e-6,"Selected send envelope bypass leaked into another path");}
    }
    // A short MIDI note must not turn a free amplitude curve into a sample gate.
    {Rig r(file,48000,64);auto c=drum::InstrumentControls{};r.set(c);auto unprocessed=r.hit();c.sound.mode=2;c.sound.envelopes[0].count=4;c.sound.envelopes[0].hold=3;c.sound.envelopes[0].points[0]={0,1};c.sound.envelopes[0].points[1]={40,.5};c.sound.envelopes[0].points[2]={100,1};c.sound.envelopes[0].points[3]={200,.7};r.set(c);auto shaped=r.hit();for(int ch=0;ch<2;++ch)for(int n=14400;n<22000;++n)check(std::abs(shaped.getSample(ch,n)-unprocessed.getSample(ch,n)*.7f)<2e-6f,"Free point placement or MIDI note-off shortened waveform");c.sound.bypassAmplitude=1;r.set(c);sameAudio(unprocessed,r.hit(),"Amplitude off did not restore full unprocessed hit after MIDI note-off");
     c.sound.bypassAmplitude=0;c.sound.envelopes[0]=drum::adsrShape(5,10,.3,10);r.set(c);auto released=r.hit();check(released.getMagnitude(0,14400,7000)==0,"Explicit sustain release fixture remained audible");c.sound.bypassAmplitude=1;r.set(c);juce::AudioBuffer<float> resumed(6,512);juce::MidiBuffer noNewNote;r.p.processBlock(resumed,noNewNote);check(resumed.getMagnitude(0,256,256)>.05,"Amplitude off failed to restore still-running sample after envelope release");sameAudio(unprocessed,r.hit(),"Bypassing released envelope retained MIDI gating");}
    // Exercise the real asynchronous preview and drawn waveform for every feed.
    {Rig r(file,48000,128);auto c=drum::InstrumentControls{};c.sound.mode=2;
     c.sound.envelopes[0]=drum::adsrShape(20,80,.3,160);c.sound.pitchAmount=7;c.sound.envelopes[1]=drum::adsrShape(15,60,.2,150);c.sound.filterOn=1;c.sound.cutoff=1700;c.sound.filterAmount=-2;c.sound.envelopes[2]=drum::adsrShape(10,90,.4,180);
     for(int send=0;send<6;++send){c.sound.sendA=c.sound.sendB=c.sound.sendC=c.sound.sendD=c.sound.sendE=c.sound.sendF=0;auto branch=std::make_shared<drum::SendProcessing>();branch->sound=c.sound;branch->tuning=send-3;c.sendProcessing[(size_t)send]=branch;}r.set(c);
     SoundEditor editor(r.p);editor.setVisible(true);editor.setSize(1200,850);auto state=r.p.getLibrary().snapshot();editor.select(r.kit,drum::findInstrument(*drum::activeKit(state),r.id));click(editor,"edit-tab-1");
     auto pixels=[&](){const auto start=juce::Time::getMillisecondCounterHiRes();bool ready=false;while(juce::Time::getMillisecondCounterHiRes()-start<10000){juce::Thread::sleep(10);juce::Timer::callPendingTimersSynchronously();if(juce::Time::getMillisecondCounterHiRes()-start>200 && control<juce::Label>(editor,"waveform-status").getText().contains("One hit")){ready=true;break;}}check(ready,"Envelope waveform preview timed out");auto& wave=control<juce::Component>(editor,"sample-waveform");auto image=wave.createComponentSnapshot({10,26,wave.getWidth()-20,wave.getHeight()-58});uint64_t hash=0;for(int y=0;y<image.getHeight();++y)for(int x=0;x<image.getWidth();++x)hash=hash*31+image.getPixelAt(x,y).getARGB();return hash;};
     for(int send=-1;send<6;++send)for(int stage=0;stage<3;++stage){control<juce::ComboBox>(editor,"waveform-view").setSelectedId(send<0?2:send+3,juce::sendNotificationSync);click(editor,stage==0?"overlay-amplitude":stage==1?"overlay-pitch":"filter-envelope-tab");auto before=pixels();auto saved=r.current();auto source=r.p.getSampleEngine().waveformFor(r.id);auto initial=drum::SampleEngine::renderPreview(source,saved,{},120,48000,send);check(initial.sample!=nullptr,"Initial envelope preview missing");auto& enabled=control<juce::ToggleButton>(editor,"editor-stage-enabled");check(enabled.getToggleState(),"Preview stage not initially enabled");enabled.setToggleState(false,juce::sendNotificationSync);auto off=pixels();if(off==before)std::cerr<<"Waveform unchanged send="<<send<<" stage="<<stage<<" status="<<control<juce::Label>(editor,"waveform-status").getText()<<"\n";check(off!=before,"Envelope bypass did not change drawn waveform");enabled.setToggleState(true,juce::sendNotificationSync);auto after=pixels();if(before!=after)std::cerr<<"Waveform round-trip mismatch send="<<send<<" stage="<<stage<<"\n";check(before==after,"Envelope preview did not restore exact drawn shape");check(saved==r.current(),"Preview round trip changed controls");auto restored=drum::SampleEngine::renderPreview(source,r.current(),{},120,48000,send);check(restored.sample!=nullptr,"Restored envelope preview missing");sameAudio(initial.sample->audio,restored.sample->audio,"Envelope preview samples changed after off/on");}
    }
    std::cout<<"Waveform preview: 21 main/all-six-send envelope off/on pixel and sample round trips passed\n";
    std::cout<<"Envelope audit: 36 main/send rate/block round trips, bypass, release, stored controls and recall passed\n";
}
